u="$1"; s=""; h=$(mktemp); while IFS= read -r l; do o=$(printf '%s' "$l" | curl -sf -D "$h" -X POST -H 'Content-Type: application/json' -H 'Accept: application/json' ${s:+-H "Mcp-Session-Id: $s"} --data-binary @- "$u"); e=$?; n=$(tr -d '\r' < "$h" | awk -F': ' 'tolower($1)=="mcp-session-id"{print $2}'); [ -n "$n" ] && s="$n"; if [ $e -ne 0 ]; then i=$(printf '%s' "$l" | sed -n 's/.*"id":\([0-9][0-9]*\).*/\1/p'); [ -n "$i" ] && printf '{"jsonrpc":"2.0","id":%s,"error":{"code":-32000,"message":"Pixel Deck is not open, or AI drawing is switched off in its Settings."}}\n' "$i"; elif [ -n "$o" ]; then printf '%s\n' "$o"; fi; done
